   "summary": "8月9日，位于郑州的国内首个全国产10万卡AI超集群正式投入使用，一期即达10万张国产AI加速卡规模，峰值算力等效全人类不间断计算200年，已对接新材料、创新药、大模型训练等26个领域超300项任务。粤港澳大湾区枢纽同步上线国产化万卡超节点集群。",
