   "summary": "2026世界人工智能大会上，华为昇腾950超节点（Atlas950SuperPoD）真机首次公开亮相，由1024张昇腾NPU组成、提供1EFLOPS FP8与2EFLOPS FP4算力、256TB统一内存编址、3μs超低时延。华为昇腾384超节点已累计部署超750套，规模应用于金融、运营商等行业。",
