   "summary": "8月2日《互联网信息服务管理办法（修订草案征求意见稿）》结束公开征求意见，草案新增“智能信息服务”专节，拟首次在行政法规层面将AI服务提供者概括为“智能信息服务提供者”。专节涵盖安全评估、数据合规、内容标识、算法规制，并要求公示技术原理与训练数据来源。",
   "decision": "算法透明与训练数据来源公示将影响招联模型采购与自研策略，建议在供应商合同中加入数据合规与可审计条款。",
