   "summary": "国家网信办、国家发改委、工信部联合印发《智能体规范应用与创新发展实施意见》，统筹高质量发展与高水平安全，回应智能体在消费、行业应用中的自主决策、网络攻击等风险。文件为智能体产业提供行动依据，推动其在安全可控前提下规范发展。",
