   "summary": "《中国大模型中标项目监测与洞察报告》显示，2026年上半年金融行业大模型中标项目达406个、同比增长110%，银行机构项目数量与金额占比均近半数。2025年金融大模型全年中标587个、披露金额15.06亿元，科大讯飞、中关村科金、阿里云列前三。",
