   "title": "育儿补贴首次申请延长至12月31日，2026年已发放2516万人",
   "summary": "国家卫健委、财政部通知将2022-2024年出生婴幼儿首次育儿补贴申请截止时间延长至2026年12月31日，补贴标准为每孩每年3600元（至满3周岁），系统新增“一键续领”。2026年度育儿补贴已提交申请2751万条、审核通过2713万条、已发放2516万人。",
   "decision": "宝宝出生后即按年申领每孩每年3600元育儿补贴；若符合2022-2024年出生婴幼儿条件，须于12月31日前通过支付宝/微信“育儿补贴”小程序提交首次申请，别错过截止期。",
   "source": "国家卫生健康委",
   "url": "https://www.nhc.gov.cn/rkjcyjtfzs/c100148/202607/6db6c47697544b97bc86bc4ac78d0b32.shtml",
