   "title": "北京市消协约谈20家儿童寝具企业，儿童床重金属与标识问题突出",
   "summary": "《人民日报》8月18日第11版报道，北京市消费者协会约谈20家儿童寝具生产企业。比较试验20款样品中15款警示标识缺失或不达标（占75%），“金多喜”样品铅含量超标10倍以上、铬超标2倍多，部分多功能婴儿床存在稳定性不足、护栏高度不够等隐患，涉事企业须10个工作日内提交整改报告。",
   "decision": "选购婴儿床/儿童床认准国家强制标准GB 28007—2024，避开无警示标识及金多喜等抽检问题款，优先参考Babycare、好孩子等全项达标样品，控制待产家具开支。",
   "source": "人民日报",
   "url": "https://paper.people.com.cn/rmrb/pc/content/202608/18/content_30175503.html",
   "firstSeen": "2026-08-18",
