   "summary": "中国疾控中心8月17日发布第32周急性呼吸道传染病哨点监测：新冠处于本次疫情波动高峰平台期、总体中流行水平，主要流行株为NB.1.8.1变异株，部分省份已出现下降趋势；同日国家卫健委宣布8月18日上午举办第四期食品安全标准大讲堂。",
   "decision": "新生儿免疫力弱，秋冬前尽量不去人多密闭场所、家人不适戴口罩；把“出生一件事”集成办理与疫苗接种规划纳入待产清单，降低交叉感染风险。",
