   "summary": "腾讯新闻8月18日报道，昆明一消费者在飞鹤奶粉中发现褐色颗粒异物引发关注，飞鹤公司回应经检测该物质为淀粉、并非有害物质，目前消费者已向相关部门投诉、事件正在进一步处理中。事件提醒家长开封奶粉后留意异物与结块。",
   "decision": "奶粉开封后留意异物、结块与异味，飞鹤事件暂定淀粉非有害但建议留存购买凭证、必要时换批次；待产奶粉预算预留退换与备选品牌空间。",
