   "summary": "健康报8月18日报道，国家医保局近日发布《检验类医疗服务价格项目立项指南（试行）》，覆盖临床检验、输血与血型、微生物、分子诊断等主要板块共662个主项目，突出以服务产出为导向、规范检验方法学价格差异、明确联检分档折扣，减轻患者负担。",
   "decision": "检验项目统一定价有望规范产检、新生儿筛查与化验收费，就诊时核对收费明细、善用医保与生育津贴直接发放，控制孕产医疗支出。",
