   "summary": "新版程序百白破疫苗首针由3月龄提前至2月龄，全程5针均含百日咳成分；国产双价HPV疫苗首次纳入国家免疫规划，2011年11月10日后出生的满13周岁女孩可免费接种2剂。特殊儿童接种判定由五类扩充至九类。",
   "decision": "宝宝2月龄起需按新程序接种百白破，建好接种本并设提醒；同时可规划女儿（如有）13周岁前免费HPV接种，做好长期健康档案。",
