   "title": "新规重塑辅食行业 守护成长提升行动强化全链条管控",
   "summary": "市场监管总局《婴幼儿辅助食品生产许可审查细则（征求意见稿）》与守护成长提升行动要求大米原料镉≤0.06mg/kg、铅≤0.2mg/kg，畜禽原料须来自自建或自控规模场，明确禁止使用蜂蜜原料。",
