   "summary": "国台办例行发布会回应英国《经济学人》罕见点名批评赖清德，发言人朱凤莲表示赖清德上台以来顽固坚持“台独”分裂立场、傲慢专横滥权乱政，假民主真独裁早已恶名远扬。",
