   "title": "国务院印发《实施就业优先战略“十五五”规划》",
   "summary": "国发〔2026〕16号印发就业优先战略“十五五”规划，明确适应人工智能发展促进就业创业、大规模职业技能培训、全力促进高校毕业生等青年就业，并将扩大内需与稳就业政策协同，稳定重点群体就业。",
   "decision": "就业是居民收入的源头，稳就业扩岗政策有助于提升消费金融目标客群偿债能力与需求韧性，招联可关注就业友好型场景。",
