   "title": "国务院发文推行常住地提供基本公共服务 国发〔2026〕11号",
   "summary": "《国务院关于推行常住地提供基本公共服务的实施意见》提出逐步消除基本公共服务与户籍挂钩因素，加强随迁子女教育保障、扩大公租房保障范围、健全就业地参加职工社保制度，促进未落户常住人口同等享有服务。",
   "decision": "常住人口公共服务均等化利好新市民与多孩家庭落户、子女教育与住房，间接扩大消费金融服务的合规客群基本盘。",
