   "title": "国务院常务会议审议公积金条例修改草案 拓宽提取使用范围",
   "summary": "7月31日国务院常务会议审议通过《国务院关于修改〈住房公积金管理条例〉的决定(草案)》，明确拓宽提取和使用范围、扩大制度覆盖面，将自住住房装修、支付物业费纳入可提取情形，并强化跨地区互认互贷。",
   "decision": "多孩家庭与青年群体福音，公积金可覆盖装修、物业费等“养房”场景，待产家庭后续置业与住房消费资金调度更灵活。",
