   "summary": "国务院总理李强8月17日主持召开国务院第十二次全体会议，强调抓紧推进“十五五”规划落地实施，坚持扩大内需战略基点，加快落实“六张网”建设实施方案。会议要求加快各类政策资金使用进度、有力促进民间投资，强化科技赋能加快新旧动能转换。",
   "decision": "宏观稳增长与“六张网”建设提速将改善信用环境与居民预期，招联可关注内需释放带来的消费信贷需求修复。",
