   "summary": "国家发展改革委副主任岳修虎主持召开会议，部署加快推进2026年新型政策性金融工具投放工作，加大对民间投资项目支持力度。下一步发改委将会同有关方面进一步加快推进各项工具落地，创新投融资机制吸引社会资本。",
   "decision": "政策性金融工具加码带动基建与民间投资，利好实体融资环境，招联可跟踪配套消费与产业场景的联动机会。",
