   "title": "商务部等9部门印发《关于进一步激发下沉市场活力 活跃县域消费的意见》",
   "summary": "商务部会同国家发展改革委、财政部等9部门联合印发意见，围绕县域消费渠道升级、业态创新、优化供给等提出18条举措，引导连锁企业加速下沉、推行连锁企业和个体户“一照多址”。意见明确支持符合条件的个人消费贷款、服务业经营主体贷款享受财政贴息，扩大新能源汽车、绿色智能产品下乡。",
   "decision": "县域消费与贴息贷款直接利好招联消费金融业务，可结合招联×联通渠道下沉县域，布局普惠消费贷与以旧换新分期。",
