   "summary": "中国人民银行8月17日宣布新增平安银行、恒丰银行、渤海银行、上海银行等8家银行类数字人民币业务运营机构并接入央行端系统，扩容后运营机构增至30家。央行表示将按市场化、法治化原则有序推进运营机构扩容。",
