   "title": "市场监管总局：“十四五”期间查处滥用行政权力排除限制竞争案件290件",
   "summary": "市场监管总局8月17日披露，“十四五”时期部署开展滥用行政权力排除、限制竞争执法专项行动，依法查处案件290件，年均办结提升至58件。涉案市级、县级政府及部门案件占比超95%，着力破除地方保护与行政性垄断。",
   "decision": "全国统一大市场建设破除区域壁垒，有利于招联跨区域消费金融业务的标准化与合规扩张。",
