   "title": "国家医保局首次遴选158个基层病种实行“同病同付”",
   "summary": "国家医保局在按病种付费3.0版分组方案中首次遴选158个基层病种（DRG 31个、DIP 127个），核心机制为同一统筹区内不同等级医疗机构执行相同支付标准。涵盖高血压、糖尿病、冠心病等常见病，引导常见病、多发病向基层分流。",
   "decision": "基层就医支付标准化有利于家庭慢病管理降本，招联可结合员工与用户健康权益完善医疗相关服务。",
