   "title": "司法部发布规范涉企行政执法为民办实事典型案例",
   "summary": "司法部发布规范涉企行政执法典型案例，本批6个案例涵盖海南、浙江、山东、江苏、山西等地，涉及权责边界规范、执法模式创新、服务供给优化等维度。司法部将巩固深化专项行动成果，推进规范涉企执法常态化长效化。",
   "decision": "涉企执法规范化降低制度性交易成本，利好招联等金融机构合规展业与地方营商环境。",
