   "title": "国家统计局发布1—7月份国民经济运行数据",
   "summary": "国家统计局8月17日公布，1—7月规模以上工业增加值同比增5.3%，服务业生产指数增4.7%，货物进出口增17.3%，社会消费商品和服务零售总额增2.6%。7月新能源乘用车零售渗透率达65.1%，连续4个月超过60%。",
   "decision": "经济总体平稳、新动能贡献提升，招联可据此优化零售信贷风险偏好与客群结构。",
