   "summary": "五部门办公厅发布通知，2026新能源汽车下乡将于近期启动，主题为“智行千县万镇，绿惠乡村万家”。落实车购税、车船税减免及县域充换电设施补短板，设置以旧换新专区，并组织保险、信贷等金融服务企业协同下乡。",
   "decision": "汽车下乡叠加以旧换新补贴与信贷服务下乡，招联可联合联通渠道拓展县域汽车分期与绿色消费金融。",
