   "title": "国家发展改革委、国家能源局印发《石油天然气发展“十五五”规划》",
   "summary": "规划提出到2030年国内油气供应量达4.4亿吨油当量，新增油气长输管道2万公里、全国管网规模达22万公里，天然气储备占全国消费比重超13%。规划首次将CCUS、绿电制氢、多能融合纳入油气主业体系，明确24项具体举措。",
   "decision": "能源保供与绿色转型为长期主线，关系家庭用能成本，招联可关注绿色消费与新能源产业链金融需求。",
