   "title": "全国医保即时结算资金达9457.31亿元 年度目标提前完成",
   "summary": "国家医保局消息，截至7月底全国医保部门共拨付医药机构即时结算资金9457.31亿元，覆盖定点医药机构75.22万家，占统筹地区定点机构90.17%，即时结算年度目标提前完成。按病种付费3.0版将建立动态监测机制。",
   "decision": "医保结算提速减少家庭垫资压力，利于招联在医疗分期等场景设计更贴合用户现金流的产品。",
