   "title": "国家外汇局：7月非银行部门跨境收支合计1.7万亿美元 同比增20%",
   "summary": "国家外汇局8月17日数据显示，7月企业、个人等非银行部门跨境收支合计1.7万亿美元，同比增长20%；外汇市场交易量4.3万亿美元，同比增8%。7月跨境资金净流入598亿美元，银行结售汇顺差183亿美元，市场供求基本平衡。",
   "decision": "外汇市场平稳、跨境资金均衡，对招联境内消费金融直接关联有限，但反映外部不确定性下宏观韧性。",
