   "title": "自然资源部印发《临时用海管理办法》",
   "summary": "自然资源部印发《临时用海管理办法》（共20条，原暂行办法同时废止），首创“需许可、可备案、不得办”三类分类管理模式，简化审批流程并强化全链条管理。涉及生态红线、改变岸线形态的需许可，海洋文旅、科研等不涉及红线的可备案。",
   "decision": "用海审批优化属营商环境改善，对招联直接关联有限，但有助于沿海地方项目合规预期。",
