   "title": "《个人贷款业务明示综合融资成本规定》8月1日起施行",
   "summary": "金融监管总局、央行联合发布规定，要求贷款人向借款人展示综合融资成本明示表，息费项目与机构全覆盖。消费金融公司、小贷公司等全部纳入，线上线下均需落实明示。",
   "decision": "招联消金须自8月1日起在新增个贷业务全面展示综合融资成本明示表，借招联×联通专项强化息费透明与合规获客。",
