   "summary": "规划部署四方面重点任务与12个专项工程，设战略性新兴产业知识产权保护、知识产权与人工智能双向赋能等工程。到2030年每万人口高价值发明专利拥有量目标超22件。",
   "decision": "招联应关注知识产权与AI双向赋能工程，加强自有风控模型与品牌商标保护，联通合作中注意数据合规。",
