   "summary": "继民法典之后我国第二部以法典命名的法律正式施行，标志生态环境法治建设迈入新境界。法典强化公众健康保障与生态环境损害赔偿制度，明确生态环境部制定生态环境基准职责。",
   "decision": "关注生态环境法典施行对绿色信贷与ESG合规的影响，招联可借联通场景推广低碳消费金融。",
