   "title": "社保补贴政策延续至年底 河北按国家要求扩大补贴范围",
   "summary": "8月19日消息，河北按国家要求延续扩大社会保险补贴范围政策，符合条件的重点行业中小微企业吸纳重点群体就业并缴费的，按个人缴费额25%给予补贴，申请期限截至2026年底。",
   "decision": "就业扶持政策延续，关注招联小微客群与联通政企客户的用工成本改善。",
