   "title": "未来10天西北太平洋或现双台风 华南云南需防强降雨",
   "summary": "中央气象台中期预报显示，未来10天西北太平洋和南海可能再生成2个台风，受副高西伸与季风槽活跃影响，华南、云南沿海局地累计雨量或突破250毫米，城市内涝、山洪与中小河流水位飙升风险叠加。",
   "decision": "极端天气呈“链条式”特征，待产家庭近期尽量避免山区自驾，关注红色预警与赴院通道安全。",
