   "title": "台风“白海豚”残涡北上 水利部升级发布洪水黄色预警",
   "summary": "台风“白海豚”虽已停编，残余涡旋经江浙沪入海北上，江苏中南部、安徽中南部、浙江、上海、江西、湖北等地有大到暴雨，宁波多区发布暴雨红/橙预警；太湖预计发生流域性较大洪水，水利部升级洪水黄色预警。",
   "decision": "妻预产期临近且华东为影响区，建议避开强降雨时段出行、远离低洼与山区，提前规划赴院路线与应急联系。",
   "source": "搜狐",
