   "title": "多部门支持河南应对“白海豚”残涡洪涝灾害",
   "summary": "国家防灾减灾救灾委针对“白海豚”残涡及强降雨对河南的严重灾害启动国家四级救灾应急响应，调拨3万件中央救灾物资与防汛物资，发改委安排3000万元中央预算内投资支持河南灾后应急恢复。",
   "decision": "灾后应急恢复机制高效运转，反映防灾减灾体系成熟；家庭可借鉴应急物资与保险预案，提升韧性。",
   "source": "水利部",
