   "title": "台风“白海豚”停编后回马枪 江浙沪遭极端暴雨",
   "summary": "“白海豚”8月11日停编，残涡却在冷空气与地形配合下折返江浙沪，湖州织里1小时降雨202.9毫米破历史极值，无锡8月累计雨量近500毫米；专家提醒“风弱雨强”型灾害隐蔽性强，切勿因停编放松警惕。",
   "decision": "残涡致灾具滞后性，山区与低洼地带需防地质灾害与城市内涝，家庭应持续关注气象预警、减少不必要外出。",
